"use client"
import Link from "next/link";
import { useParams } from "next/navigation";

export default function Pokmod() {
const params=useParams()
const id=params.id as string
  return (
    <div className="flex justify-center items-center inset-0 bg-black/50">
      <div className="">
        <h2> modal view</h2>
        <p> pokemonid: {id} </p>
        <h1> full page view </h1>
        <Link href={`/Pokemonn/${id}`}>Click here</Link>
      </div>
      
    </div>
  );
}
